use aap::caps::http_client;
use aap::caps::state_rw;
use aap::caps::types::{FeedDocument, FetchFailure};

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input this call received under `last-input` before any
        // fetching, so the record exists even if a later fetch traps.
        let input = subscriptions.urls.join("\n");
        state_rw::put("last-input", &input);

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
